// 确定性洗牌：同一题每次加载选项位置一致（seed=题号），answer 字段真实反映正确标签
function examShuffle(arr, seed) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = (seed * 2654435761 + i * 7919) % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
// 打乱选项并返回 { options, answer }：母题约定 A 为正确项
function examShuffleOptions(opts, seed) {
  const labels = ['A', 'B', 'C', 'D'];
  const entries = Object.entries(opts);
  const correctText = opts['A'];
  const shuffled = examShuffle(entries, seed);
  const out = {};
  let answer = 'A';
  shuffled.forEach(([k, v], i) => {
    out[labels[i]] = v;
    if (v === correctText) answer = labels[i];
  });
  return { options: out, answer };
}
